import { Game, Play } from "../types";

const GAMES_KEY = "football-stats-games";
const PLAYS_KEY = "football-stats-plays";

export function getGames(): Game[] {
  try {
    if (typeof window === "undefined") return [];
    const stored = localStorage.getItem(GAMES_KEY);
    return stored ? JSON.parse(stored) : [];
  } catch (error) {
    console.error("Error reading games:", error);
    return [];
  }
}

export function saveGame(game: Game): void {
  try {
    if (typeof window === "undefined") return;
    const games = getGames();
    const existingIndex = games.findIndex(g => g.id === game.id);
    
    if (existingIndex >= 0) {
      games[existingIndex] = game;
    } else {
      games.push(game);
    }
    
    localStorage.setItem(GAMES_KEY, JSON.stringify(games));
  } catch (error) {
    console.error("Error saving game:", error);
    throw new Error("Failed to save game");
  }
}

export function getPlays(gameId?: string): Play[] {
  try {
    if (typeof window === "undefined") return [];
    const stored = localStorage.getItem(PLAYS_KEY);
    const allPlays = stored ? JSON.parse(stored) : [];
    
    if (gameId) {
      return allPlays.filter((play: Play) => play.gameId === gameId);
    }
    
    return allPlays;
  } catch (error) {
    console.error("Error reading plays:", error);
    return [];
  }
}

export function savePlay(play: Play): void {
  try {
    if (typeof window === "undefined") return;
    const plays = getPlays();
    plays.push(play);
    localStorage.setItem(PLAYS_KEY, JSON.stringify(plays));
  } catch (error) {
    console.error("Error saving play:", error);
    throw new Error("Failed to save play");
  }
}

export function deleteGame(gameId: string): void {
  try {
    if (typeof window === "undefined") return;
    
    // Remove game
    const games = getGames().filter(game => game.id !== gameId);
    localStorage.setItem(GAMES_KEY, JSON.stringify(games));
    
    // Remove associated plays
    const plays = getPlays().filter(play => play.gameId !== gameId);
    localStorage.setItem(PLAYS_KEY, JSON.stringify(plays));
  } catch (error) {
    console.error("Error deleting game:", error);
    throw new Error("Failed to delete game");
  }
}

export function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).substr(2);
}
