"use client";

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Game, Player, FOOTBALL_POSITIONS } from "@/types";
import { saveGame, generateId, getGames, deleteGame } from "@/lib/storage";

export default function GameCreationForm() {
  const [formData, setFormData] = useState({
    season: "",
    time: "",
    date: "",
    location: "",
    homeTeamName: "",
    awayTeamName: "",
  });

  const [homeRoster, setHomeRoster] = useState<Player[]>([
    { jersey: "", name: "", position: "" }
  ]);

  const [awayRoster, setAwayRoster] = useState<Player[]>([
    { jersey: "", name: "", position: "" }
  ]);

  const [games, setGames] = useState<Game[]>([]);
  const [alert, setAlert] = useState<{ type: "success" | "error"; message: string } | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Load games on component mount
  useEffect(() => {
    const loadedGames = getGames();
    setGames(loadedGames);
  }, []);

  const handleInputChange = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleRosterChange = (
    roster: Player[],
    setRoster: React.Dispatch<React.SetStateAction<Player[]>>,
    index: number,
    field: keyof Player,
    value: string
  ) => {
    const newRoster = [...roster];
    newRoster[index] = { ...newRoster[index], [field]: value };
    setRoster(newRoster);
  };

  const addPlayer = (
    roster: Player[],
    setRoster: React.Dispatch<React.SetStateAction<Player[]>>
  ) => {
    setRoster([...roster, { jersey: "", name: "", position: "" }]);
  };

  const removePlayer = (
    roster: Player[],
    setRoster: React.Dispatch<React.SetStateAction<Player[]>>,
    index: number
  ) => {
    if (roster.length > 1) {
      setRoster(roster.filter((_, i) => i !== index));
    }
  };

  const validateForm = (): string | null => {
    if (!formData.season.trim()) return "Season is required";
    if (!formData.date) return "Date is required";
    if (!formData.time) return "Time is required";
    if (!formData.location.trim()) return "Location is required";
    if (!formData.homeTeamName.trim()) return "Home team name is required";
    if (!formData.awayTeamName.trim()) return "Away team name is required";

    // Validate home roster
    const validHomeRoster = homeRoster.filter(p => p.jersey.trim() && p.name.trim() && p.position.trim());
    if (validHomeRoster.length === 0) return "At least one home team player is required";

    // Validate away roster
    const validAwayRoster = awayRoster.filter(p => p.jersey.trim() && p.name.trim() && p.position.trim());
    if (validAwayRoster.length === 0) return "At least one away team player is required";

    return null;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setAlert(null);

    const validationError = validateForm();
    if (validationError) {
      setAlert({ type: "error", message: validationError });
      setIsSubmitting(false);
      return;
    }

    try {
      const validHomeRoster = homeRoster.filter(p => p.jersey.trim() && p.name.trim() && p.position.trim());
      const validAwayRoster = awayRoster.filter(p => p.jersey.trim() && p.name.trim() && p.position.trim());

      const game: Game = {
        id: generateId(),
        season: formData.season.trim(),
        time: formData.time,
        date: formData.date,
        location: formData.location.trim(),
        homeTeamName: formData.homeTeamName.trim(),
        awayTeamName: formData.awayTeamName.trim(),
        homeRoster: validHomeRoster,
        awayRoster: validAwayRoster,
      };

      saveGame(game);
      setAlert({ type: "success", message: "Game created successfully!" });

      // Reset form
      setFormData({
        season: "",
        time: "",
        date: "",
        location: "",
        homeTeamName: "",
        awayTeamName: "",
      });
      setHomeRoster([{ jersey: "", name: "", position: "" }]);
      setAwayRoster([{ jersey: "", name: "", position: "" }]);

      // Refresh games list
      const updatedGames = getGames();
      setGames(updatedGames);

    } catch (error) {
      setAlert({ type: "error", message: "Failed to create game. Please try again." });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDeleteGame = async (gameId: string) => {
    try {
      deleteGame(gameId);
      const updatedGames = getGames();
      setGames(updatedGames);
      setAlert({ type: "success", message: "Game deleted successfully!" });
    } catch (error) {
      setAlert({ type: "error", message: "Failed to delete game. Please try again." });
    }
  };

  const renderRosterSection = (
    title: string,
    roster: Player[],
    setRoster: React.Dispatch<React.SetStateAction<Player[]>>
  ) => (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg">{title}</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {roster.map((player, index) => (
          <div key={index} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-4 border rounded-lg">
            <div>
              <Label htmlFor={`${title}-jersey-${index}`}>Jersey #</Label>
              <Input
                id={`${title}-jersey-${index}`}
                type="text"
                placeholder="00"
                value={player.jersey}
                onChange={(e) => handleRosterChange(roster, setRoster, index, "jersey", e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor={`${title}-name-${index}`}>Player Name</Label>
              <Input
                id={`${title}-name-${index}`}
                type="text"
                placeholder="Player Name"
                value={player.name}
                onChange={(e) => handleRosterChange(roster, setRoster, index, "name", e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor={`${title}-position-${index}`}>Position</Label>
              <Select
                value={player.position}
                onValueChange={(value) => handleRosterChange(roster, setRoster, index, "position", value)}
              >
                <SelectTrigger className="mt-1">
                  <SelectValue placeholder="Select position" />
                </SelectTrigger>
                <SelectContent>
                  {FOOTBALL_POSITIONS.map((position) => (
                    <SelectItem key={position} value={position}>
                      {position}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="flex items-end">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => removePlayer(roster, setRoster, index)}
                disabled={roster.length === 1}
                className="w-full"
              >
                Remove
              </Button>
            </div>
          </div>
        ))}
        <Button
          type="button"
          variant="outline"
          onClick={() => addPlayer(roster, setRoster)}
          className="w-full"
        >
          Add Player
        </Button>
      </CardContent>
    </Card>
  );

  return (
    <div className="max-w-6xl mx-auto p-6 space-y-6">
      <div className="text-center">
        <h2 className="text-2xl font-bold mb-2">Create New Game</h2>
        <p className="text-muted-foreground">Set up a new football game with team rosters</p>
      </div>

      {alert && (
        <Alert className={alert.type === "error" ? "border-red-500 bg-red-50" : "border-green-500 bg-green-50"}>
          <AlertDescription className={alert.type === "error" ? "text-red-700" : "text-green-700"}>
            {alert.message}
          </AlertDescription>
        </Alert>
      )}

      <form onSubmit={handleSubmit} className="space-y-6">
        <Card>
          <CardHeader>
            <CardTitle>Game Details</CardTitle>
          </CardHeader>
          <CardContent className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="season">Season</Label>
              <Input
                id="season"
                type="text"
                placeholder="2024"
                value={formData.season}
                onChange={(e) => handleInputChange("season", e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor="date">Date</Label>
              <Input
                id="date"
                type="date"
                value={formData.date}
                onChange={(e) => handleInputChange("date", e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor="time">Time</Label>
              <Input
                id="time"
                type="time"
                value={formData.time}
                onChange={(e) => handleInputChange("time", e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor="location">Location</Label>
              <Input
                id="location"
                type="text"
                placeholder="Stadium Name"
                value={formData.location}
                onChange={(e) => handleInputChange("location", e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor="homeTeam">Home Team Name</Label>
              <Input
                id="homeTeam"
                type="text"
                placeholder="Home Team"
                value={formData.homeTeamName}
                onChange={(e) => handleInputChange("homeTeamName", e.target.value)}
                className="mt-1"
              />
            </div>
            <div>
              <Label htmlFor="awayTeam">Away Team Name</Label>
              <Input
                id="awayTeam"
                type="text"
                placeholder="Away Team"
                value={formData.awayTeamName}
                onChange={(e) => handleInputChange("awayTeamName", e.target.value)}
                className="mt-1"
              />
            </div>
          </CardContent>
        </Card>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {renderRosterSection("Home Team Roster", homeRoster, setHomeRoster)}
          {renderRosterSection("Away Team Roster", awayRoster, setAwayRoster)}
        </div>

        <div className="flex justify-center">
          <Button type="submit" disabled={isSubmitting} className="px-8 py-2">
            {isSubmitting ? "Creating Game..." : "Create Game"}
          </Button>
        </div>
      </form>
    </div>
  );
}
