export interface Player {
  jersey: string;
  name: string;
  position: string;
}

export interface Game {
  id: string;
  season: string;
  time: string;
  date: string;
  location: string;
  homeTeamName: string;
  awayTeamName: string;
  homeRoster: Player[];
  awayRoster: Player[];
}

export interface Play {
  id: string;
  gameId: string;
  time: string;
  quarter: string;
  possession: "home" | "away";
  down: number;
  distance: number;
  yardLine: string;
  playType: string;
  playerInvolved: string;
  yardsGained: number;
  result: string;
  tackler: string;
  penalty?: string;
}

